#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int S, T, P;
    cin >> S >> T >> P;

    vector<int> height(S);
    for (int &h : height) cin >> h;

    vector<vector<int>> graph(S);
    for (int i = 0; i < T; ++i) {
        int u, v;
        cin >> u >> v;
        --u;
        --v;

        if (height[u] > height[v]) graph[u].push_back(v);
        else if (height[v] > height[u]) graph[v].push_back(u);
    }

    vector<int> memo(S, -1);

    function<int(int)> longest = [&](int u) {
        if (memo[u] != -1) return memo[u];

        int best = 0;
        for (int v : graph[u]) {
            best = max(best, 1 + longest(v));
        }
        return memo[u] = best;
    };

    cout << longest(P - 1) << '\n';
    return 0;
}
